CREATE DATABASE IF NOT EXISTS customer_behaviour;
USE customer_behaviour;
SELECT * FROM customer LIMIT 5;

-- 1. Revenue Analysis-
-- Compared total revenue generated by male and female customers.
SELECT gender, SUM(purchase_amount) AS total_revenue
FROM customer
GROUP BY gender;

-- 2. Discount and Spending Analysis.
-- Identified discount users whose purchase amounts were at or above the overall average.
SELECT customer_id, purchase_amount
FROM customer
WHERE discount_applied = 'Yes'
AND purchase_amount >= (SELECT AVG(purchase_amount) FROM customer);

-- 3.Product Rating Analysis.
-- Rank top 5 products by average review rating.
SELECT item_purchased, ROUND(AVG(review_rating), 2) AS average_review_rating
FROM customer
GROUP BY item_purchased
ORDER BY AVG(review_rating) DESC
LIMIT 5;

-- 4. Shipping Analysis.
-- Compared average purchase amounts for Standard and Express Shipping.
SELECT shipping_type, ROUND(AVG(purchase_amount), 2) AS average_purchase_amount
FROM customer
WHERE shipping_type IN('Express', 'Standard')
GROUP BY shipping_type;

-- 5. Subscription Analysis.
-- Compared customer counts, average spending, and total revenue between subscribers and 
-- non-subscribers.
SELECT subscription_status,
	   COUNT(customer_id) AS total_customer,
       ROUND(AVG(purchase_amount), 2) AS average_spending,
       SUM(purchase_amount) AS total_revenue
FROM customer
GROUP BY subscription_status;

-- 6. Discount Dependency Analysis.
-- Identified the top 5 Products by percentage of purchases with discounts applied.
SELECT item_purchased,
	   ROUND(SUM(
       CASE WHEN discount_applied='Yes' THEN 1 ELSE 0 END)/
       COUNT(*)*100, 2) AS percent
FROM customer
GROUP BY item_purchased
ORDER BY percent DESC
LIMIT 5;

-- 7. Customer Segmentation
-- Classified customers into New, Returning, and Loyal segments based on previous purchases.
WITH classified_customer AS(
SELECT CASE
	   WHEN previous_purchases = 1 THEN 'New'
       WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
       ELSE 'Loyal' END AS segments
FROM customer
)
SELECT segments, COUNT(*) AS total_customer
FROM classified_customer
GROUP BY segments;

-- 8. Product Popularity Analysis.
-- Identified the top 3 most purchased products within each category.
WITH top_3 AS(
SELECT category, item_purchased, COUNT(*) AS total_orders,
	   ROW_NUMBER() OVER(PARTITION BY category ORDER BY COUNT(*) DESC) AS rnk
FROM customer
GROUP BY category, item_purchased
)
SELECT category, item_purchased, total_orders
FROM top_3
WHERE rnk <= 3;

-- 9. Repeat Buyer Analysis.
-- Compared subscription status among customers with more than 5 previous purchases.
SELECT subscription_status,
	   COUNT(*) AS repeated_buyer
FROM customer
WHERE previous_purchases>5
GROUP BY subscription_status;

SELECT * FROM customer LIMIT 5;
-- 10. Age Group Revenue Analysis.
-- Compared total revenue across customer age groups.
SELECT age_group, SUM(purchase_amount) AS total_revenue
FROM customer
GROUP BY age_group
ORDER BY total_revenue DESC;